[9051]={["aftermath"]="Torwa thanked the tester and asked how the creature had reacted; his question did not yet establish the toxin's success.",["atomIDs"]={"9051:description:1-56","9051:description:59-151","9051:description:154-266","9051:description:271-335","9051:description:338-410","9051:objective:1-41","9051:objective:43-121"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9051:completion:1-14","9051:completion:17-39","9051:completion:44-93"},["minimumStage"]=2,["objectiveSummary"]="Test Torwa's poisoned barb on a living devilsaur.",["opening"]="Killing a devilsaur merely opened its territory to another, leaving Torwa's hunting and survival no easier. He hoped a toxin would pacify one without killing it, but did not know how quickly the dose would act.",["pending"]="{actor} would test the barb on a living devilsaur.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} tested the toxin and reported to Torwa.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="b3cad26ebc7ad650b5c77a8960849516dbeba338ba41cab8f62d4ee3f512937a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9052]={["aftermath"]="Torwa combined the ingredients with soil he had already collected from Un'Goro.",["atomIDs"]={"9052:description:1-105","9052:description:108-192","9052:description:197-292","9052:description:295-412","9052:objective:1-90"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9052:completion:1-24","9052:completion:29-100"},["minimumStage"]=2,["objectiveSummary"]="Gather eight bloodcaps and eight Gorishi stings for Torwa.",["opening"]="Torwa sought a nonlethal toxin to calm one of Un'Goro's great beasts. Mushrooms within bloodpetal sprouts and stings from the Slithering Scar's insects would supply its first ingredients.",["pending"]="{actor} would gather the mushrooms and insect stings.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the bloodcaps and stings to Torwa.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="151973476dd4f0fcb4cc65c2637d4cd04e5bc7e66cbd25c8a4e4c4ddaa7c3c10",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
