[9120]={["atomIDs"]={"9120:description:1-62","9120:description:64-166","9120:description:168-230","9120:description:235-296","9120:description:298-347","9120:objective:1-84"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Bring Kel'Thuzad's phylactery to Light's Hope.",["opening"]="The phylactery remained after Naxxramas's master fell, carrying the danger that the lich might reform. Taking it to Light's Hope for payment preserved that troubling object rather than destroying it on the spot.",["pending"]="{actor} would carry the phylactery to Light's Hope.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Kel'Thuzad's phylactery to Montoy.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="1841458db13498aea0f94767c453ebbc75713a2e203bd210500e1b9c8c98b2ed",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9121]={["aftermath"]="Angela began the cloaking that would allow entry through Plaguewood's rune portal.",["atomIDs"]={"9121:description:1-79","9121:description:81-180","9121:description:182-200","9121:description:205-329","9121:description:331-425","9121:description:427-510","9121:objective:1-153","9121:objective:155-200"},["endingAtomIDs"]={"9121:completion:1-34","9121:completion:36-69","9121:completion:71-168"},["opening"]="Angela's modified Kirin Tor cloaking could bypass Naxxramas's portal wards. For honored standing, the expensive route required crystals, an orb and gold, with reduced terms available at greater dedication.",["pending"]="{actor} planned to supply the honored entry requirements.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled Angela's crystals, orb and payment request.",["sourceHash"]="fc33e2c8d7f4c215b8792dc6d65eaa643e8eb62d34f555b76f1d065149be8964",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9122]={["aftermath"]="Angela prepared the enchantment for access through the rune portal.",["atomIDs"]={"9122:description:1-79","9122:description:81-180","9122:description:182-200","9122:description:205-350","9122:description:352-390","9122:description:392-496","9122:objective:1-135","9122:objective:137-182"},["endingAtomIDs"]={"9122:completion:1-34","9122:completion:36-69","9122:completion:71-168"},["opening"]="The wards had yielded to a new form of permanent arcane concealment. Revered service allowed the Dawn to absorb part of its cost, leaving two arcane crystals, one nexus crystal and gold to supply.",["pending"]="{actor} meant to fulfill the revered cloaking requirements.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the requested crystals and payment.",["sourceHash"]="eb81f5c67f3cbfc951d27a7462b04089b58f856cfee8d8fe404404c8fb51df6f",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9123]={["aftermath"]="Angela began the working that would make the Plaguewood portal usable.",["atomIDs"]={"9123:description:1-79","9123:description:81-180","9123:description:182-200","9123:description:205-350","9123:description:352-455","9123:description:457-492","9123:objective:1-117","9123:objective:119-159"},["endingAtomIDs"]={"9123:completion:1-34","9123:completion:36-69","9123:completion:71-168"},["opening"]="For exalted service, Angela waived the cost of the Dawn's portal-cloaking method. The offer promised an entrance into the citadel, without making any claim about the dangers inside.",["pending"]="{actor} intended to receive the offered arcane cloaking.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the no-cost attunement audience.",["sourceHash"]="bb200279c542ac6337c4d53746578a62ebb5f023d58de9b96e8e9762e0edc5f3",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9124]={["aftermath"]="Leopold offered the same insignia exchange for further bundles.",["atomIDs"]={"9124:description:1-61","9124:description:66-111","9124:description:116-184","9124:description:186-268","9124:description:270-383","9124:description:385-480","9124:objective:1-94"},["endingAtomIDs"]={"9124:completion:1-26","9124:completion:28-69","9124:completion:71-134"},["opening"]="Leopold's armor work repeatedly exhausted its supply of crypt fiend components. Those entering the citadel brought core materials, but other collectors could support the missing stock through bundles of parts.",["pending"]="{actor} planned to bring thirty crypt fiend parts.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the bundle to Leopold.",["sourceHash"]="65a24215ab41325a2d6d6a39e2e884ae502de9edecdfb5871277cdb45fc07779",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9126]={["atomIDs"]={"9126:description:1-87","9126:description:89-254","9126:description:259-279","9126:description:281-364","9126:description:366-390","9126:objective:1-93"},["opening"]="Rohan needed large quantities of Scourge bone for Don Julio's armor pattern. The shortage remained even when prospective wearers supplied its major components.",["pending"]="{actor} meant to gather thirty bone fragments.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Rohan with the fragments.",["sourceHash"]="3dd9c80881734fad8347a1ab0c83a35bdf7ccfc55994215cc428812bfb8796c2",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9128]={["atomIDs"]={"9128:description:1-22","9128:description:24-55","9128:description:57-99","9128:description:101-176","9128:description:181-255","9128:description:257-276","9128:description:281-367","9128:objective:1-101"},["opening"]="Angela commissioned cores from elementals across the world. Bundles supported her work at the chapel and could be exchanged for insignias used by the quartermaster.",["pending"]="{actor} intended to gather thirty elemental cores.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the cores to Angela.",["sourceHash"]="555ac45005f9c0fea5448244516ab57c87b3f8d3bb113b9655570f666e416e7d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9131]={["aftermath"]="Korfax accepted the stock while leaving the commission open for more.",["atomIDs"]={"9131:description:1-41","9131:description:43-68","9131:description:70-106","9131:description:108-139","9131:description:144-218","9131:description:220-332","9131:description:337-408","9131:description:410-438","9131:objective:1-83"},["endingAtomIDs"]={"9131:completion:1-22","9131:completion:24-66"},["opening"]="Korfax's admiration for Dreadnaught armor came with a practical shortage. Dark Iron scrap was needed to assemble sets for the Dawn's champions.",["pending"]="{actor} planned to bring thirty scraps to Korfax.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the requested scrap.",["sourceHash"]="1e1c6e873721b1c5808f3142d3dde2073d4408224079bda1c9b91ebb01c5c5db",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9136]={["aftermath"]="Rayne thanked the contribution and continued accepting more.",["atomIDs"]={"9136:description:1-94","9136:description:96-253","9136:description:258-351","9136:description:356-483","9136:objective:1-79"},["endingAtomIDs"]={"9136:completion:1-22","9136:completion:27-39","9136:completion:44-93"},["opening"]="Rayne explained why the seemingly small task mattered: without savage fronds, Dreamwalker armor could not be made. Support from both Dawn and Crusade let her offer a choice of insignias.",["pending"]="{actor} meant to gather thirty savage fronds.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the fronds to Rayne.",["sourceHash"]="5f073d9955b4bf42c859e7da189b583e890ccbdc88011adf3e9f18e6c529bd87",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9141]={["aftermath"]="Metz explained that each token bought a writ whose filled order belonged with Stonebruiser.",["atomIDs"]={"9141:description:1-16","9141:description:18-22","9141:description:24-105","9141:description:107-125","9141:description:127-194","9141:description:199-290","9141:description:292-329","9141:description:334-422","9141:objective:1-107"},["endingAtomIDs"]={"9141:completion:1-97","9141:completion:99-183","9141:completion:185-191","9141:completion:193-197","9141:completion:199-218"},["opening"]="Metz would not issue coveted work orders merely on arrival. A valor token was the required evidence of dedication before a crafter could enter the front-line contracting system.",["pending"]="{actor} intended to present a valor token.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} gave Metz the token.",["sourceHash"]="6282ee933968a9c23cb81cdbebf8ddce42dd0eab39aecd891ac4ff0ca498b6d7",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9142]={["atomIDs"]={"9142:description:1-24","9142:description:26-69"},["objectiveSummary"]="Trade one valor token for a craftsman writ.",["opening"]="Metz's established exchange remained one valor token for another work order. The new writ would create a contract to fulfill or discard.",["pending"]="{actor} planned to exchange a token for another writ.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed another token exchange with Metz.",["sourceHash"]="90748927d423d1fc8caa0a7e62e2963d2e308afb8eaf77613405763911de74c3",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9153]={["aftermath"]="Helleran welcomed the local gain but urged rest followed by a return to the front, warning that the ground still had to be held.",["atomIDs"]={"9153:description:1-86","9153:description:88-206","9153:description:211-269","9153:description:274-362","9153:description:364-474","9153:objective:1-52","9153:objective:54-123","9153:objective:125-237"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9153:completion:1-21","9153:completion:23-110","9153:completion:115-224","9153:completion:229-353"},["minimumStage"]=2,["objectiveSummary"]="Weaken a Scourge necropolis's defenses and bring Helleran ten necrotic runes.",["opening"]="Flying necropolises threatened both factions. Magical circles anchored their incursions, and destroying the Scourge surrounding those sites could strip away the defenses sustaining the invasion.",["pending"]="{actor} would attack an invasion site and recover its necrotic runes.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned ten runes after striking the necropolis's defenders.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="b43e0c35a4573c60b7090b3a8c9be29e01f74c1356db9f8161ed1725eb141d42",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9154]={["aftermath"]="The Keeper welcomed the aid and placed faith in the recruit's existing abilities against the invasion.",["atomIDs"]={"9154:description:1-70","9154:description:73-112","9154:description:115-202","9154:description:207-328","9154:objective:1-115"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9154:completion:1-78","9154:completion:80-132","9154:completion:134-235"},["minimumStage"]=2,["objectiveSummary"]="Deliver the call to arms to the Keeper of the Rolls.",["opening"]="The Argent Dawn sought every capable defender against the Scourge's renewed numbers. Its announcement called willing recruits to Light's Hope rather than promising time for training before the fighting.",["pending"]="{actor} would carry the announcement to Light's Hope.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} answered the call before the Keeper of the Rolls.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="4041979e811241a14e40a7725e5d4f79bda702abcf49dc81752c44f1c254aec6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9165]={["aftermath"]="Metz added his signature and acknowledged the work.",["atomIDs"]={"9165:description:1-69","9165:description:71-147","9165:description:152-181","9165:description:186-247","9165:description:249-348","9165:description:353-395","9165:description:397-504","9165:objective:1-117"},["endingAtomIDs"]={"9165:completion:1-54","9165:completion:59-77","9165:completion:79-95","9165:completion:97-137","9165:completion:139-161"},["opening"]="Didier credited the caravan's arrival to outside help against the Scourge. Chambers still had to sign the safe-passage writ before it could be taken back to the chapel's dispatch commander.",["pending"]="{actor} meant to deliver the signed passage writ.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the signed document to Metz.",["sourceHash"]="582a08413fbeed4a9258e48305e2ed746ee2150d88f5fb8677eabe054ca4777d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9178]={["aftermath"]="Stonebruiser assigned the stock to the infantry's blunt weapons.",["atomIDs"]={"9178:description:1-135","9178:description:140-157","9178:description:162-184","9178:description:189-303","9178:description:308-361","9178:description:366-406","9178:objective:1-155"},["endingAtomIDs"]={"9178:completion:1-65"},["opening"]="The smithing contract demanded a bulk delivery of dense weightstones with its intact writ. Payment depended on completing the order and keeping the document undamaged.",["pending"]="{actor} intended to supply one hundred twenty weightstones and the writ.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the stones and contract to Stonebruiser.",["sourceHash"]="122b415f2060d14efb33da84eb8fdc692ecc73f751344b67a06014a08feb5967",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9179]={["aftermath"]="Stonebruiser welcomed more armor for the troops.",["atomIDs"]={"9179:description:1-135","9179:description:140-157","9179:description:162-185","9179:description:190-304","9179:description:309-362","9179:description:367-407","9179:objective:1-159"},["endingAtomIDs"]={"9179:completion:1-26","9179:completion:28-41"},["opening"]="Three plate chests made up the armor order for the chapel. The accompanying writ established the contract, so the finished pieces alone were not the whole delivery.",["pending"]="{actor} planned to deliver three plate chests with the writ.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the chest-armor contract.",["sourceHash"]="2105b7b9b482f22602bb83cf7862346fb1b6c3be2954e1630b99f9224342a8b0",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9181]={["aftermath"]="Stonebruiser expected the hammers to complement the weightstones already being stockpiled.",["atomIDs"]={"9181:description:1-135","9181:description:140-157","9181:description:162-180","9181:description:185-299","9181:description:304-357","9181:description:362-402","9181:objective:1-149"},["endingAtomIDs"]={"9181:completion:1-67"},["opening"]="The written order called for three volcanic hammers at Light's Hope. Its terms required both the weapons and the unaltered contract before an insignia could be claimed.",["pending"]="{actor} meant to provide the three hammers and writ.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the hammer delivery.",["sourceHash"]="b942364bb641b34d8d04115cf0ec95a24a16cb38e4da426a4f13d7f564f5875d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9182]={["aftermath"]="Stonebruiser thought them smaller than expected but honored the bargain.",["atomIDs"]={"9182:description:1-135","9182:description:140-158","9182:description:163-188","9182:description:193-307","9182:description:312-365","9182:description:370-410","9182:objective:1-163"},["endingAtomIDs"]={"9182:completion:1-35","9182:completion:37-65"},["opening"]="Metz's order specified three huge thorium battleaxes. The contract's intact condition remained part of the terms alongside the weapons themselves.",["pending"]="{actor} intended to deliver the axes with their writ.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the thorium axe order.",["sourceHash"]="c7abc385fa9af4973269969bbc66e1fbabda5749282c4cc3997277f5298d7ed1",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9183]={["aftermath"]="Stonebruiser doubted the headpieces' quality as protection against the Scourge's freezing attacks.",["atomIDs"]={"9183:description:1-135","9183:description:140-156","9183:description:161-179","9183:description:184-298","9183:description:303-356","9183:description:361-401","9183:objective:1-149"},["endingAtomIDs"]={"9183:completion:1-134"},["opening"]="An armor contract in Metz's hand specified three radiant circlets. The headpieces and intact writ were due together at the chapel before the bearer could receive an insignia.",["pending"]="{actor} planned to supply the three circlets and writ.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the circlet contract.",["sourceHash"]="2bae3416ff2af71ab04392685e065d57b70517269c21899712f001f88afaa785",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9184]={["aftermath"]="Stonebruiser accepted them with a brief play on their wicked name.",["atomIDs"]={"9184:description:1-135","9184:description:140-157","9184:description:162-189","9184:description:194-308","9184:description:313-366","9184:description:371-411","9184:objective:1-166"},["endingAtomIDs"]={"9184:completion:1-12","9184:completion:14-20"},["opening"]="Ten leather headbands formed the order's entire cargo. Metz's seal established payment for that exact quantity, with alteration or damage to the writ voiding the agreement.",["pending"]="{actor} meant to deliver ten headbands with their contract.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the headband order.",["sourceHash"]="68fdd1f2d8b8bda0b6c8dc8964be66947588642fc49ba9c526361ea0e6b40cd3",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9185]={["aftermath"]="Stonebruiser described uses beyond reinforcement and set one aside to keep his teapot warm.",["atomIDs"]={"9185:description:1-135","9185:description:140-157","9185:description:162-182","9185:description:187-301","9185:description:306-359","9185:description:364-404","9185:objective:1-152"},["endingAtomIDs"]={"9185:completion:1-41","9185:completion:43-117","9185:completion:119-173"},["opening"]="The quartermaster's supply order called for twenty-five rugged kits rather than finished armor. Delivery of both kits and contract would fulfill the work in exchange for an insignia.",["pending"]="{actor} intended to bring the kits and writ to Stonebruiser.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the twenty-five armor kits.",["sourceHash"]="1abd4928cbf7be82a990c079ac45ed99d9ec6c0d012b465bcc13ed35b9e58a40",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9186]={["aftermath"]="Stonebruiser compared their wickedness favorably to the headbands.",["atomIDs"]={"9186:description:1-135","9186:description:140-157","9186:description:162-184","9186:description:189-303","9186:description:308-361","9186:description:366-406","9186:objective:1-157"},["endingAtomIDs"]={"9186:completion:1-105"},["opening"]="Nine wicked leather belts were due under this signed order. Keeping the document intact mattered as much to its validity as meeting the listed quantity.",["pending"]="{actor} planned to deliver nine belts and the writ.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the belt contract.",["sourceHash"]="6e7ac8de3982e621b0ce8dfc3107aead87b6fdc90dbf5e76cee2481756a0e9bf",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9187]={["aftermath"]="Stonebruiser expected the druids to appreciate their craftsmanship.",["atomIDs"]={"9187:description:1-135","9187:description:140-158","9187:description:163-184","9187:description:189-303","9187:description:308-361","9187:description:366-406","9187:objective:1-156"},["endingAtomIDs"]={"9187:completion:1-97","9187:completion:99-114"},["opening"]="Metz requested four pairs of runic leather pants for delivery to the chapel. The writ fixed the required goods and promised an insignia once its undamaged terms were fulfilled.",["pending"]="{actor} meant to supply the four pairs with the contract.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the runic leather order.",["sourceHash"]="872a6c2e5623e0f449c0cc8e1c207e201024777d86dc63e73d2637818b6a4f7e",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
